export async function readFromFile(filePath: string): Promise<string[]> {
    return new Promise((resolve, reject) => {
        try {
            const data = readFileSync(filePath, 'utf-8');
            resolve(data.split('\n'));
        } catch (err) {
            reject(err);
        }
    });
}

