pub fn vowel_count(text: &str) -> usize {
    let vowels = ['a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'];
    text.chars()
        .filter(|&c| vowels.contains(&c))
        .count()
}

pub fn count_vowels(text: &str) -> usize {
    let vowels = ['a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'];
    text.chars().filter(|c| vowels.contains(c)).count()
}

