function generateFibonacci(n: number): number[] {
  const fib: number[] = [0, 1];
  if (n <= 2) return fib.slice(0, n);
  for (let i = 2; i < n; i++) {
    fib.push(fib[i - 1] + fib[i - 2]);
  }
  return fib;
}

