    }
  }
};

export interface Request {
  type: string;
  payload: any;
}

export interface Result {
  status: string;
  message: string;
  data?: any;
}

function handleRequest(request: Request): Result {
  try {
    switch (request.type) {
      case 'addTask':
        const { task } = request.payload;
        // Logic to add task to the task store
        return { status: 'success', message: 'Task added', data: task };
      case 'removeTask':
        const { taskId } = request.payload;
        // Logic to remove task from the task store
        return { status: 'success', message: 'Task removed', data: taskId };
      default:
        return { status: 'error', message: 'Unknown request type' };
    }
  } catch (error) {
    return { status: 'error', message: `Error handling request: ${error.message}` };
  }
}

export function processRequests(requests: Request[]): Result[] {
  return requests.map(handleRequest);
}

